module Prob_5_37_Fig_5_25 (output reg y, input x_in, clock, reset_b);  parameter a = 3'b000, b = 3'b001, c = 3'b010, d = 3'b011, e = 3'b100, f = 3'b101, g = 3'b110;  reg [2: 0] state, next_state;  always @ (posedge clock, negedge reset_b)     if (reset_b == 0) state <= a;    else state <= next_state;  always @ (state, x_in) begin    y = 0;    next_state = a;    case (state)        a:		begin y = 0; if (x_in == 0) next_state = a; else next_state = b; end      b:		begin y = 0; if (x_in == 0) next_state = c; else next_state = d; end 	       c:		begin y = 0; if (x_in == 0) next_state = a; else next_state = d; end       d:		if (x_in == 0) begin y = 0; next_state = e; end			else begin y = 1; next_state = f; end       e:		if (x_in == 0) begin y = 0;  next_state = a; end			else begin y = 1; next_state = f; end       f:		if (x_in == 0) begin y = 0;  next_state = g; end			else begin y = 1; next_state = f; end      g:		if (x_in == 0) begin y = 0; next_state = a; end   else begin y = 1; next_state = f; end       default:	next_state = a;    endcase  endendmodulemodule Problem_5_37_Fig_5_26 (output reg y, input x_in, clock, reset_b);  parameter a = 3'b000, b = 3'b001, c = 3'b010, d = 3'b011, e = 3'b100;  reg [2: 0] state, next_state;  always @ (posedge clock, negedge reset_b)     if (reset_b == 0) state <= a;    else state <= next_state;
  always @ (state, x_in) begin    y = 0;    next_state = a;    case (state)        a:		begin y = 0; if (x_in == 0) next_state = a; else next_state = b; end       b:		begin y = 0; if (x_in == 0) next_state = c; else next_state = d; end 	       c:		begin y = 0; if (x_in == 0) next_state = a; else next_state = d; end      d:		if (x_in == 0) begin y = 0; next_state = e; end			else begin y = 1; next_state = d; end       e:		if (x_in == 0) begin y = 0;  next_state = a; end			else begin y = 1; next_state = d; end      default:	next_state = a;    endcase  endendmodule